window.__BUNDLE__={"generatedAt":"2026-11-05T01:48:47.365255+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-10-29","archiveCutoff":"2021-11-06","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":268,"arxiv":1412,"total":1680},"freshness":{"latestPaperDate":"2026-11-04","latestPublishedDate":"2026-11-04","latestBatchCount":302,"newInLast24h":344,"newInLast48h":1087},"historyTotal":30258,"topicCounts":{"Multi-Agent":3186,"Evaluation":16617,"Planning":2217,"Memory":592,"Code Agent":1215,"Interpretability":1006,"Agentic RAG":1577,"Agentic Search":2117,"RL for LLM":1597,"Reasoning":8050,"Hallucination":1309,"Post-Training":3341,"Alignment":3902,"World Model":606,"Tool Use":1478,"Agent Safety":2765,"Computer Use":403,"Reflection":1077,"VLM Training":2393,"LLM Training":3902,"Fine-tuning":4717,"Multimodal Agent":176,"Agent Framework":975,"Error Attribution":189,"Data Engine":601},"count":36,"recentTotal":1901,"archiveCount":0,"archiveTotal":28357,"sources":{"hf":44,"arxiv":1857,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"url":"https://arxiv.org/abs/2611.05275","id":"arxiv:2611.05275","title":"Route Anything: A Study of Model and Policy Routing for General-Purpose AI Systems","source":"hf","pdf":"https://arxiv.org/pdf/2611.05275.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Evaluation"],"authors":["Pengfei Zhou","Yixing Ma","Hexin Wang","Weidong Tang","Zhenglin Wan","Wangbo Zhao","Yang You"],"date":"2026-11-04","topics":["Evaluation"],"upvotes":86,"arxiv":"https://arxiv.org/abs/2611.05275","hfUrl":"https://huggingface.co/papers/2611.05275","abstract":"Artificial general intelligence (AGI) requires a method that can understand, generate, reason, and act across diverse domains and modalities. Rather than relying on a single model to master every capability, a promising path toward AGI now is to orchestrate a heterogeneous ecosystem of specialized models, tools, and policies (candidates) into a unified AI system. At the heart of this vision lies a fundamental question: how can an AI system dynamically select and coordinate the most capable candidate for each task while balancing performance and computational cost? In this work, we present Route Anything, a unified framework for studying model and policy routing across general-purpose AI systems. We develop a unified theoretical foundation that characterizes optimal routing under quality--cost trade-offs and establishes how the information available to a router determines its attainable p"},{"url":"https://arxiv.org/abs/2611.04814","id":"arxiv:2611.04814","title":"Think Less, Locally: Local Preference Learning for Reasoning Compression","source":"hf","pdf":"https://arxiv.org/pdf/2611.04814.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","LLM Training","Reasoning","Evaluation"],"authors":["Muyao Yuan","Liyan Xu","Weizhan Zhang","Muyan Jiao","Jiangnan Li","Jinchao Zhang","Jie Zhou"],"date":"2026-11-04","topics":["Post-Training","LLM Training","Reasoning","Evaluation"],"upvotes":65,"arxiv":"https://arxiv.org/abs/2611.04814","hfUrl":"https://huggingface.co/papers/2611.04814","abstract":"Large reasoning models achieve strong performance on challenging tasks, but their long chain-of-thought often incurs substantial inference costs by continuing to deliberate after sufficient information has been obtained. Existing reasoning compression methods primarily operate on reasoning trajectories, paying less attention to the local decision of whether further reasoning is necessary given the current state. We propose LoCo, a local preference learning method for reasoning compression. LoCo detects candidate overthinking states from the model's own traces, freezes the corresponding reasoning prefixes, regenerates shorter verified continuations from the same states, and trains on the resulting state-conditioned preference pairs with DPO. This formulation teaches the model when to continue reasoning and when to conclude, rather than simply encouraging shorter trajectories overall. We c"},{"url":"https://arxiv.org/abs/2611.04916","id":"arxiv:2611.04916","title":"Behind Video Generation: Observations and Insights on Multimodal Understanding from Kling","source":"hf","pdf":"https://arxiv.org/pdf/2611.04916.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","Evaluation","Alignment"],"authors":["Kling Team","Dong Chen","Jialu Chen","Xinlong Chen","Yifan Dai","Haotian Dong","Binzong Geng","Yushuo Guan","Minghui Guo","Guanlin He","Guanxiao He","Jingyun Hua","Yanwei Huang","Yiyan Ji","Xueping Jia","Yizhuo Jia","Bozhou Li","Jiaze Li","Min Li","Shihao Li","Shujie Li","Shengyi Liao","Weihong Lin","Shiyuan Liu","Xinyu Liu","Siyang Mao","Xiaoru Qu","Dianmo Sheng","Yang Shi","Jiafu Tang","Longxiang Tang","Yuqi Tang","Chengzhuo Tong","Kuo Wang","Qixun Wang","Rui Wang","Tianduo Wang","Yuran Wang","Zekun Wang","Zihao Wang","Boyang Xia","Yifan Xu","Liu Yang","Zhenlong Yuan","Bohan Zeng","Mujin Zhang","Yuanxing Zhang","Zhicheng Zhang","Zhuoran Zhang","Yuanhong Zheng","Kun Gai","Chengru Song","Pengfei Wan"],"date":"2026-11-04","topics":["Post-Training","Evaluation","Alignment"],"upvotes":51,"arxiv":"https://arxiv.org/abs/2611.04916","hfUrl":"https://huggingface.co/papers/2611.04916","abstract":"Video generation has progressed from isolated clips to coherent short-form audiovisual sequences, and the bottleneck is shifting from rendering to semantic control. This report summarizes the observations and insights on multimodal understanding gained from successive generations of Kling. We argue that generation quality is the projection of multimodal understanding through the entire data--conditioning--alignment--evaluation chain, and we examine this chain module by module. Kling-MLLM, a shared multimodal foundation model that unifies image, video, audio, synchronized audio--video, and interleaved inputs, is specialized for each downstream module. Because a DiT is trained on far fewer training samples than a language model, we treat captioning as a semantic contract that maximizes description density, and extend it to reference-grounded captioning that makes reference bindings explici"},{"url":"https://arxiv.org/abs/2611.05193","id":"arxiv:2611.05193","title":"Factorized MLLM Embeddings for Composed Image Retrieval","source":"hf","pdf":"https://arxiv.org/pdf/2611.05193.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Reasoning","Evaluation"],"authors":["WonJun Moon","Seongchan Kim","Dahun Kim","Seungryong Kim"],"date":"2026-11-04","topics":["Reasoning","Evaluation"],"upvotes":44,"arxiv":"https://arxiv.org/abs/2611.05193","hfUrl":"https://huggingface.co/papers/2611.05193","abstract":"Composed Image Retrieval (CIR) aims to retrieve a target image given a reference image and a modification text. Although recent approaches leveraging Multimodal Large Language Models (MLLMs) have shown significant progress, we argue that the MLLM's compositional understanding remains underutilized. This stems from directly mapping composed queries into a retrieval embedding via contrastive supervision alone, without explicitly resolving the intended visual modifications. In this work, we introduce Factorized MLLM Embeddings (FactEmbed), which decouples compositional query comprehension from building discriminative embeddings. Rather than directly projecting the composed query into a single embedding without internal reasoning, FactEmbed employs a set of factorized latents that simulate the intended visual modifications via an intermediate target imagination objective. This process encour"},{"url":"https://arxiv.org/abs/2611.05036","id":"arxiv:2611.05036","title":"ToolSpace: Scaling Tool-Centric Environment Synthesis for Long-Horizon Agents","source":"hf","pdf":"https://arxiv.org/pdf/2611.05036.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Tool Use","Evaluation"],"authors":["Guanting Dong","Zhichao Sun","Xinyu Yang","Rui Wang","Xin Deng","Jiajie Jin","Zhixiong Yang","Junhao Huang","Han Han","Mingyu Ma","Xiaotao Wang","Yuyang Hu","Xiaoshuai Song","Xiaoxi Li","Jiejun Tan","Zhecan Wang","Shihan Dou","Honglin Guo","Zhiheng Xi","Tao Gui","Tao Ji","Qi Zhang","Yutao Zhu","Ji-Rong Wen","Zhicheng Dou"],"date":"2026-11-04","topics":["Tool Use","Evaluation"],"upvotes":34,"arxiv":"https://arxiv.org/abs/2611.05036","hfUrl":"https://huggingface.co/papers/2611.05036","abstract":"Large language models are deployed as long-horizon agents that compose diverse tools across MCP services into executable workflows. Existing MCP environment-scaling methods are data-centric: they first synthesize a database and scenario, then derive tools and tasks from them. As a result, tool interfaces may not match real ones, tool compositions are not grounded in execution, and tasks rarely span more than one environment. We propose ToolSpace, a tool-centric framework that reverses this order. ToolSpace mines data, state, and retry dependencies from adjacent calls in execution traces of real MCP services and open agent corpora, using deterministic rules rather than LLM judgment, and clusters the resulting weighted tool-composition graph into environments. Databases are synthesized only for state-mutating environments, while query and stateless tools replay recorded returns. ToolSpace "},{"url":"https://arxiv.org/abs/2611.05280","id":"arxiv:2611.05280","title":"YANAMI: A Large-Scale Multimodal Dataset and Benchmark for Multiturn Stateful Interaction","source":"hf","pdf":"https://arxiv.org/pdf/2611.05280.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Reasoning","Evaluation","Fine-tuning","World Model"],"authors":["Shengyu Wang","Tengyue Nong","Junming Liu","Haosong Peng","Siyu Li","Ruiqi Lei","Fushuo Huo","Yuhao Pan","Yunfeng Fan","Ding Wang","Nan Cheng","Haozhao Wang","Wenchao Xu"],"date":"2026-11-04","topics":["Reasoning","Evaluation","Fine-tuning","World Model"],"upvotes":26,"arxiv":"https://arxiv.org/abs/2611.05280","hfUrl":"https://huggingface.co/papers/2611.05280","abstract":"Unified Multimodal Models (UMMs) integrate visual understanding, generation, and editing within a single unified framework. However, existing unified multimodal datasets and benchmarks remain dominated by single-turn tasks. Even in recent multi-turn datasets, many turns can be solved independently without tracking information across turns. Consequently, they provide limited supervision and evaluation for multimodal stateful interaction, which requires models to understand, maintain, update, and faithfully realize evolving dialogue states across turns. To address this gap, we introduce YANAMI, the first large-scale multimodal dialogue dataset and benchmark for stateful interaction, comprising YANAMI-400K and YANAMI-Bench. YANAMI-400K contains 400K multi-turn multimodal dialogues, with more than 2M images and 2.6M dialogue turns. The dialogues span four representative scenarios: Multi-Imag"},{"url":"https://arxiv.org/abs/2611.04418","id":"arxiv:2611.04418","title":"VidUEU-Agent: A Data-Curation Agent for Multimodal Understanding, Editing, and Unified Tasks","source":"hf","pdf":"https://arxiv.org/pdf/2611.04418.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Evaluation","Fine-tuning","Agent Framework"],"authors":["Tengju Ru","Weitong Lian","Zecong Tang","Lingyi Meng","Haoran Li","Zhejun Cui","Yichen Zhu","Hangshuo Cao","Qi Kang","Yechi Liu","Kaixuan Wang","Yu-Jie Yuan","Chunwei Wang","Yu Zhang","Bo Dai"],"date":"2026-11-04","topics":["Evaluation","Fine-tuning","Agent Framework"],"upvotes":23,"arxiv":"https://arxiv.org/abs/2611.04418","hfUrl":"https://huggingface.co/papers/2611.04418","abstract":"The advancement of multimodal learning is heavily constrained by the scarcity and high annotation cost of high-quality instruction data. While raw videos offer an abundant and dynamic source of visual knowledge, transforming them into precise instruction data remains highly challenging. To bridge this gap, we present VidUEU-Agent, an automated pipeline that synthesizes instruction data from raw videos for multimodal understanding, editing, and unified tasks. VidUEU-Agent follows a four-stage pipeline: it performs global perception to filter low-quality shots, mines keyframes and multimodal signals, constructs metadata and routes the metadata to synthesize instruction samples. More importantly, our agent framework can autonomously iterate the data distribution based on downstream training results, thereby optimizing data quality, balance, and training effectiveness. Scaling this pipeline,"},{"url":"https://arxiv.org/abs/2611.04035","id":"arxiv:2611.04035","title":"Recursa: Toward Recursively Self-Improving Foundation Model Systems","source":"hf","pdf":"https://arxiv.org/pdf/2611.04035.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["LLM Training","Evaluation","Reflection"],"authors":["Erkang Zhu","Yin Lin","Xiaorong Shi","Xuanrui Lin","Jingren Zhou"],"date":"2026-11-04","topics":["LLM Training","Evaluation","Reflection"],"upvotes":11,"arxiv":"https://arxiv.org/abs/2611.04035","hfUrl":"https://huggingface.co/papers/2611.04035","abstract":"Foundation models in changing environments can encounter unfamiliar domain knowledge that their original training did not cover. However, new domains rarely provide large amounts of expert-created training data or reliable supervisory signals for further training. We introduce Recursa, a foundation model system that adapts to new domains by learning from its own experience without human experts or a stronger teacher model. Recursa uses a knowledge repository to store what it learns: domain-specific skills and instructions on when to apply them, along with memories of past task experiences and reflections on what to improve. Recursa bootstraps the repository from domain materials and then refines it through recursive self-improvement. It uses parallel learners to execute tasks and synthesize local improvements, then validates and merges the improvements into the knowledge repository. On H"},{"url":"https://arxiv.org/abs/2611.04449","id":"arxiv:2611.04449","title":"Near-Zero Token Embeddings Silently Stall Training in Gated Sequence Models","source":"hf","pdf":"https://arxiv.org/pdf/2611.04449.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["LLM Training"],"authors":["Xin Liu","Boyuan Sun","Yuxin Wang","Haoran Song","Mingjian Zhao","Mengyu Liu"],"date":"2026-11-04","topics":["LLM Training"],"upvotes":7,"arxiv":"https://arxiv.org/abs/2611.04449","hfUrl":"https://huggingface.co/papers/2611.04449","abstract":"Among 291 surveyed open-weight language model repositories (280 distinct embedding tables), 52.6% of untied gated and hybrid checkpoints (20/38) contain reachable input embeddings with norms below $10^{-6}$, compared with 0% of weight-tied models. Such near-zero rows can arise during pretraining when unseen rare or template tokens receive zero input gradients while AdamW weight decay shrinks untied embeddings. In tested Transformer configurations, non-initial positions or a BOS token prevent this failure mode. In gated sequence models (Mamba, Gated DeltaNet, xLSTM), a near-zero token can amplify input-embedding gradients by more than 30 orders of magnitude (up to 35). At zero input, current-token readout factors (SiLU gates or linear queries) vanish, suppressing historical-state readout. Residual RMS values can then fall below the square root of the RMSNorm floor across consecutive layer"},{"url":"https://arxiv.org/abs/2611.03685","id":"arxiv:2611.03685","title":"LOLPlay: Benchmarking Real-Time Visual Agents in League of Legends","source":"hf","pdf":"https://arxiv.org/pdf/2611.03685.pdf","submittedDate":"2026-10-25","announceDate":"2026-11-04","tags":["Reasoning","Evaluation","Multimodal Agent"],"authors":["Zhaojian Yu"],"date":"2026-11-04","topics":["Reasoning","Evaluation","Multimodal Agent"],"upvotes":6,"arxiv":"https://arxiv.org/abs/2611.03685","hfUrl":"https://huggingface.co/papers/2611.03685","abstract":"Visual agents need to coordinate reasoning and action while their environment evolves during inference. We introduce LOLPlay, a benchmark in native \\emph{League of Legends} with 36 champion-specific tasks spanning resource management, combat, cooperation, and objectives. Agents interact through screenshots and mouse--keyboard actions; automated initialization and 82 executable subgoal checks distinguish partial progress from completion. Across 324 task evaluations of three models at three reasoning-effort settings, GPT-6 Astra achieves the highest task success rate of 25.0\\% at low and medium effort, and the highest subgoal success rate of 40.3\\% at medium effort. However, high effort improves neither metric over low effort for any model. For Astra, longer requests leave fewer interaction rounds, suggesting a cost to additional reasoning in real-time control. Trajectories reveal incomple"},{"url":"https://arxiv.org/abs/2611.04467","id":"arxiv:2611.04467","title":"Is Forgetting Unified? Exploring Concept Unlearning in Unified Multimodal Models","source":"hf","pdf":"https://arxiv.org/pdf/2611.04467.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Evaluation"],"authors":["Zhongkai Xue","Junkai Chen","Mingcong Lei","Rumo Zhang","Yixiao Liu","Zhimin Sun","Shu Wu","Qiang Liu","Lihua Zhang","Liang Wang"],"date":"2026-11-04","topics":["Evaluation"],"upvotes":2,"arxiv":"https://arxiv.org/abs/2611.04467","hfUrl":"https://huggingface.co/papers/2611.04467","abstract":"Unified multimodal models (UMMs) integrate image generation and visual understanding, but are existing single-pathway unlearning methods sufficient to suppress target concepts across both? In this work, we study cross-pathway concept unlearning. Our goal is to prevent a model from both generating images of a target concept and identifying it in input images, while preserving other capabilities. To this end, we introduce UUBench, a diagnostic benchmark covering 30 target concepts and 60 semantically related neighboring concepts. Experiments on representative UMMs show that the evaluated single-pathway methods achieve limited joint forgetting: generation-side editors strongly suppress target generation but yield limited forgetting in visual understanding, while understanding-side baselines struggle to achieve substantial forgetting even in their own pathway. Their direct composition also y"},{"url":"https://arxiv.org/abs/2611.05255","id":"arxiv:2611.05255","title":"Going Deeper With Memories","source":"hf","pdf":"https://arxiv.org/pdf/2611.05255.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Reasoning"],"authors":["Afshin Khadangi"],"date":"2026-11-04","topics":["Reasoning"],"upvotes":1,"arxiv":"https://arxiv.org/abs/2611.05255","hfUrl":"https://huggingface.co/papers/2611.05255","abstract":"Byte level language models avoid tokenizer dependence and provide universal coverage, but processing every byte at full resolution is expensive. We introduce DeepMem, a causal multiscale architecture that separates semantic compression from exact byte preservation. A learned invertible subband transform constructs a hierarchy of shorter sequences, while a lossless carrier and explicit detail sidebands preserve byte identity. Fast weight memory blocks operate along the encoder, with iterative shared state computation at the compressed bottleneck, while an attention based super resolution decoder restores byte resolution representations. DeepMem achieves stronger language modeling performance than a matched byte level Transformer on FineWeb-Edu and PG19, and obtains the best macro average performance across the evaluated FLORES languages. It also improves PIQA accuracy while remaining comp"},{"url":"https://arxiv.org/abs/2611.03998","id":"arxiv:2611.03998","title":"Dory1.0-4B: A Looped Normalized-GPT","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.03998.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["LLM Training","Evaluation","Fine-tuning"],"authors":["Maxim Fishman","Simeng Sun","Shantanu Acharya","Faisal Ladhak","Brian Chmiel","Santiago Akle Serano","Ron Banner","Boris Ginsburg","Krishna C. Puvvada"],"date":"2026-11-04","topics":["LLM Training","Evaluation","Fine-tuning"],"upvotes":6,"arxiv":"https://arxiv.org/abs/2611.03998","hfUrl":"https://huggingface.co/papers/2611.03998","abstract":"We introduce Dory1.0-4B, a 4-billion-parameter looped (latent-recurrent) language model with elastic depth: a single checkpoint serves different inference compute budgets. Dory1.0-4B is built on a normalized Transformer (nGPT) backbone with interleaved sliding-window and full-attention layers, organized into an input block, a shared recurrent block, and an output block. At inference, the recurrent block can be applied a variable number of times. We pre-trained Dory1.0-4B on 6 trillion tokens. The first 4.5 trillion tokens were trained in NVFP4, and additional pre-training then extended the context length to 256K tokens. Next, we post-trained the model using Supervised Fine-Tuning (SFT) and Reinforcement Learning with Verifiable Rewards (RLVR), with a difficulty-aware loop curriculum that routes harder prompts to deeper loops. Increasing the loop count improves accuracy, with the largest "},{"url":"https://arxiv.org/abs/2611.05345","id":"arxiv:2611.05345","title":"Adversarial Speculative Reasoning Improves Long Horizon Agents","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.05345.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Reasoning","Evaluation"],"authors":["Hongyin Luo","Wei Fang","Lijie Yang","Owen Stepan","Daniel Suit","Jeff Krapf","Dana Wensberg","Jack O'Brien"],"date":"2026-11-04","topics":["Reasoning","Evaluation"],"upvotes":6,"arxiv":"https://arxiv.org/abs/2611.05345","hfUrl":"https://huggingface.co/papers/2611.05345","abstract":"Speculative decoding has been treated purely as a systems optimization that speeds up large language model decoding without changing the model behavior. Under this view, the growing effort to train better draft models has been focused solely on acceptance rate. We argue that this view does not hold true for long-horizon agent reasoning. Measuring frontier open-weight models on complex agentic tasks with different speculative decoding approaches, we found that numerical noise grows within verification windows, and the draft acceptance results of the thinking process can change the output distribution of the model after 30 steps, thus noticeably influencing the reasoning accuracy of long-horizon agents in random directions. In this work, we improve the reasoning capability of target models by controlling such noise. While we cannot change the overall token distribution verified by the targ"},{"url":"https://arxiv.org/abs/2610.40488","id":"arxiv:2610.40488","title":"rTaste: Do Research Agents Have Taste? Evaluating Early Stage Research Judgment","source":"arxiv","pdf":"https://arxiv.org/pdf/2610.40488.pdf","submittedDate":"2026-10-29","announceDate":"2026-11-04","tags":["Agentic Search"],"authors":["Art Kanke"],"date":"2026-11-04","topics":["Agentic Search"],"upvotes":3,"arxiv":"https://arxiv.org/abs/2610.40488","hfUrl":"https://huggingface.co/papers/2610.40488","abstract":"Do research agents have taste, the judgment of which experiments are worth running before their outcomes are known? We give six frontier models seven recent NLP papers. Each model, working as a research agent alone or as a team, proposes minimum viable experiments (MVEs), forecasts whether each will pass a threshold it sets and ranks them. A separate executor then attempts every MVE, including those ranked last, and three model auditors judge the results. Of 415 MVEs, 194 are judged sound, valuable and new, but fewer than half of these (73) are also judged beyond the seed paper and non obvious. The agents' first choices match the auditors' most valued experiment more often than a random pick, but are not shown to improve on choosing the experiment written first. Their forecasts beat a base rate but are not measurably more accurate than those of a fresh instance of the same model given on"},{"url":"https://arxiv.org/abs/2611.04079","id":"arxiv:2611.04079","title":"AlgoPilot: Cross-Paradigm Reasoning in Language Models via Strategy Selection and Guidance","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04079.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["LLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"authors":["Yilun Hao","Ruixiao Yang","Hudson Hilal","Yongchao Chen","Kaizhi Qian","Yada Zhu","Yang Zhang","Chuchu Fan"],"date":"2026-11-04","topics":["LLM Training","Reasoning","Planning","Evaluation","Fine-tuning","RL for LLM"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04079","abstract":"Real-world problems span diverse domains, including program synthesis, symbolic reasoning, planning, and optimization, and often require fundamentally different solution paradigms. A central challenge for LLM-based reasoning is twofold: identifying an appropriate problem-solving approach and formulating it correctly. In this paper, we propose AlgoPilot, a cross-paradigm reasoning framework that enables adaptive selection of the solving approaches and structured problem formulation prior to execution. The AlgoPilot framework contains three components: 1) a SteerLM, trained via supervised fine-tuning (SFT) and reinforcement learning (RL), that adaptively selects the solving strategy (paradigm and modes) based on input problems, 2) the corresponding expert GuideLM, trained via SFT, that generates structured formulation guidance tailored to the selected strategy, and 3) an ExecutionLM that g"},{"url":"https://arxiv.org/abs/2611.05263","id":"arxiv:2611.05263","title":"JHiMA-WebRL: A Joint Hierarchical Multi-Agent Reinforcement Learning Framework for Long-Horizon Web Tasks","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.05263.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","Multi-Agent","Planning","Computer Use","Fine-tuning"],"authors":["Shanka Subhra Mondal","Jiayun Wang"],"date":"2026-11-04","topics":["Post-Training","Multi-Agent","Planning","Computer Use","Fine-tuning"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.05263","abstract":"Multimodal web agents have shown promising capabilities for interacting with websites through graphical user interfaces (GUIs), yet realistic web tasks often require long-horizon, multi-step planning that remains challenging for monolithic policies. Such agents must jointly infer high-level plans, navigate through intermediate states, track progress over extended interaction histories, and execute visually grounded actions. Although prior work has explored modular multi-agent systems with a separate planner, the planner is typically not updated jointly with the actor. We investigate whether explicitly separating and jointly training planning and execution provides a stronger inductive bias for long-horizon web navigation. We introduce JHiMA-WebRL, a joint hierarchical multi-agent reinforcement learning framework for web agents that couples a task decomposer with an actor. To train the de"},{"url":"https://arxiv.org/abs/2611.04977","id":"arxiv:2611.04977","title":"GeoFaham: Domain-Specialized Multi-Agent Geospatial Analytics for Disaster Response","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04977.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Multi-Agent","Reasoning","Planning","Code Agent","Evaluation"],"authors":["Muhammad Sohail Danish","Gilles Q. Hacheme","Akram Zaytar","Satej S. Soman","Inbal Becker-Reshef","Juan Lavista Ferres","Salman Khan","Girmaw Abebe Tadesse"],"date":"2026-11-04","topics":["Multi-Agent","Reasoning","Planning","Code Agent","Evaluation"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04977","abstract":"Real-world geospatial decision support requires more than single-step retrieval or code generation. Disaster-response questions often involve multi-source workflows that combine spatial databases, map-derived features, satellite imagery, raster products, and reusable geospatial artifacts, where correctness depends on preserving spatial scope, temporal context, and intermediate execution state. While large language models and coding agents offer a promising interface for such workflows, they struggle with geospatial-specific failure modes, including handling large artifacts, selecting the wrong evidence source, losing spatial or temporal metadata, and applying invalid geometric operations. We introduce GeoFaham, a domain-specialized multi-agent system for geospatial disaster analytics. GeoFaham decomposes workflows into specialist agents for vector operations, map feature retrieval, image"},{"url":"https://arxiv.org/abs/2611.04632","id":"arxiv:2611.04632","title":"Self-Privileged Fine-Tuning","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04632.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"authors":["Yangrong Hu","Xueyu Zhou","Yue Wu","Jian Huang"],"date":"2026-11-04","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04632","abstract":"Supervised fine-tuning (SFT) is a key component of language model post-training, enabling effective task adaptation and serving as an important foundation for subsequent reinforcement learning. Recent methods seek to improve SFT by introducing token-level weights into the training objective, where these weights are typically derived from a model's output distribution at each token position. To better understand how such weighting schemes affect SFT, we analyze their optimization objectives and theoretically characterize the target distributions they induce. Our analysis shows that dynamic weighting methods, such as Dynamic Fine-Tuning (DFT), induce a heavily sharpened distribution, whereas static weighting methods fit a target distribution proportional to the product of the data distribution and a frozen prior. These findings suggest that static weighting provides a more stable training "},{"url":"https://arxiv.org/abs/2611.04073","id":"arxiv:2611.04073","title":"Computer-Use Agents Gain Little Benefit from a World Model When Conditioned on Tutorials","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04073.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["Agentic RAG","Agentic Search","Reasoning","Planning","World Model"],"authors":["Anh Nguyen","Tianyi Xu","Phat Tran","Harry Yu","Huazheng Wang","Stefan Lee"],"date":"2026-11-04","topics":["Agentic RAG","Agentic Search","Reasoning","Planning","World Model"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04073","abstract":"Recent work has improved computer-use agents (CUAs) by combining retrieved task-relevant tutorials and look-ahead planning using world models with MLLM judges. However, the contribution of each component -- tutorials, the judge, and the world model -- to overall improvement has not been evaluated in isolation. To fill this gap, we first construct OSWorld-Tutorial and ScienceBoard-Tutorial: two datasets for CUAs with curated multimodal tutorials, covering everyday and scientific domains. We then propose RAG-PolicyJudge (RAG-PJ), a policy-judge framework for CUAs conditioned on task-specific tutorials: the policy proposes candidate actions, and the judge selects among them. To isolate the effect of world models given tutorials, we compare RAG-PJ with and without common world models: using either zero-shot text-based descriptions of next states or an oracle that returns ground-truth visual "},{"url":"https://arxiv.org/abs/2611.04811","id":"arxiv:2611.04811","title":"NightIQA: A Comprehensive Dataset and Benchmark for MLLM-Based Nighttime Image Quality Assessment","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04811.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"authors":["Yiding Tian","Jiaojiao Yi","Jiayuan Lu","Pufan Xu","Jinlin Wu","Changyuan Wen","Hongyuan Yu"],"date":"2026-11-04","topics":["Post-Training","LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04811","abstract":"Nighttime images are inherently susceptible to complex, compound degradations, making accurate quality assessment exceptionally challenging. Score-based IQA methods condense quality into a single number, lacking the multi-dimensional, language-grounded reasoning required for nighttime evaluation. Multimodal Large Language Models (MLLMs) offer a more comprehensive alternative, yet remain constrained by a critical data gap: existing real-world IQA datasets are overwhelmingly daytime-centric and often built from outdated captures, while synthetic alternatives lack nighttime-specific degradation modeling, yielding artifacts far removed from authentic nighttime conditions. To bridge this gap, we present NightIQA, a dataset and benchmark suite purpose-built for MLLM-based nighttime IQA. It comprises three core components: NightIQA-Real, a real-world dataset of 1,769 high-resolution images that"},{"url":"https://arxiv.org/abs/2611.03937","id":"arxiv:2611.03937","title":"FlowBench: Counterfactual Imagination Training for Spatial Intelligence","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.03937.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["VLM Training","Reasoning","Planning","Fine-tuning","World Model"],"authors":["Yifan Liu","Baihan Zhang","Khai Loong Aw","Klemen Kotar","Daniel L. K. Yamins"],"date":"2026-11-04","topics":["VLM Training","Reasoning","Planning","Fine-tuning","World Model"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.03937","abstract":"Humans imagine scene changes under hypothetical motions, an ability central to spatial reasoning and robotic planning. However, this capability remains underexplored in vision-language models and world models. We formalize this capability as Counterfactual Spatial Imagination (CSI) and introduce FlowBench, a resource for training and evaluating both, with 428K training examples spanning simulated and real-world scenes, household environments and tabletop manipulation, and diverse question types. A scalable, fully automatic pipeline pairs each hypothetical motion with spatial questions and, in simulation, exact outcome frames and optical flow. For VLMs, proprietary models exhibit an imagination gap, performing worse when motion outcomes must be inferred than when observed, and open-source models perform near chance; fine-tuning Qwen3-VL-8B on FlowBench-Sim-Train raises its accuracy by 29."},{"url":"https://arxiv.org/abs/2611.04228","id":"arxiv:2611.04228","title":"DualWorldBench: Can Agents Plan Deliveries across Symbolic and Grounded Worlds?","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04228.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Reasoning","Planning","Evaluation","Multimodal Agent"],"authors":["Yang Chen","Bin Wen","Danyang Peng","Hong-Jie You","Zi-Qiao Shang","Lan-Zhe Guo"],"date":"2026-11-04","topics":["Reasoning","Planning","Evaluation","Multimodal Agent"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04228","abstract":"Recent multimodal agents have shown promising progress in embodied planning and web interaction. However, existing evaluations often rely on simplified tasks with limited combinatorial structure, leaving it unclear whether current agents can robustly integrate perception and reasoning for multi-goal planning under temporal, physical, and multimodal constraints. We introduce DualWorldBench, a unified benchmark for evaluating agent planning under controlled symbolic--temporal and grounded--topological complexity. Built around a shared pickup--delivery interface, DualWorldBench consists of three complementary components: TextWorld, which isolates symbolic planning under varying task compositions and release dynamics; SimWorld, which evaluates grounded path planning under controlled topological variation with text, image, or multimodal inputs; and DualWorld-VQA, a diagnostic suite spanning p"},{"url":"https://arxiv.org/abs/2611.04834","id":"arxiv:2611.04834","title":"Feeling of Knowing in Large Language Models","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04834.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","LLM Training","Alignment","Fine-tuning"],"authors":["Zichuan Fu","Xian Wu","Jingtong Gao","Wenlin Zhang","Jiaxuan Li","Binhao Wang","Yimin Deng","Guojing Li","Xiaopeng Li","Derong Xu","Yefeng Zheng","Xiangyu Zhao"],"date":"2026-11-04","topics":["Post-Training","LLM Training","Alignment","Fine-tuning"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04834","abstract":"Post-training updates change what large language models (LLMs) can answer, but may leave their answerability judgments misaligned. We study this knowledge-judgment desynchronization through functional feeling of knowing (FoK), which supports selective generation, retrieval triggering, and model routing without implying subjective experience. We propose two trainable channels: a knowledge channel that changes answerability and a FoK channel that judges the current knowledge state. Three stages train them: on-policy supervised fine-tuning (OP-SFT) updates knowledge from corrected on-policy answers; knowledge-delta FoK training (K$Δ$-FT) adapts judgments across intermediate knowledge states; and FoK-guided policy optimization (FGPO) trains the subsequent answer or explanation. Factual-QA experiments, cross-dataset evaluation, and three sequential updates show that explicit FoK alignment imp"},{"url":"https://arxiv.org/abs/2611.05066","id":"arxiv:2611.05066","title":"VIGOR: Visual Gain Ordering for Hallucination Mitigation in Multimodal Discrete Diffusion Language Models","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.05066.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["VLM Training","Reasoning","Hallucination","Evaluation"],"authors":["Junzhe Chen","Tian Qin","Eugenie Shi","Tianshu Zhang","Qiang Ju","Lijie Wen"],"date":"2026-11-04","topics":["VLM Training","Reasoning","Hallucination","Evaluation"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.05066","abstract":"Multimodal discrete diffusion language models (dLLMs) generate responses through iterative mask prediction and offer a promising alternative to autoregressive large vision-language models. However, they still suffer from hallucination, producing outputs that are plausible under language priors but insufficiently grounded in the image. We argue that hallucination in multimodal dLLMs is not only a token prediction problem, but also a premature commitment problem: during iterative denoising, some masked positions are unmasked too early because their confidence is driven more by language priors than by visual evidence, and these early commitments can bias later generation. To address this issue, we propose Visual Gain Ordering (VIGOR), a training-free and plug-and-play inference strategy that reorders masked positions according to counterfactual visual evidence. At each denoising step, VIGOR"},{"url":"https://arxiv.org/abs/2611.05358","id":"arxiv:2611.05358","title":"Suppressing Misaligned Behaviors in Language Models, Durably","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.05358.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","LLM Training","Alignment","Fine-tuning"],"authors":["Luxi He","Pengcheng Jiang","Jifan Zhang","Jiawei Han","Danqi Chen"],"date":"2026-11-04","topics":["Post-Training","LLM Training","Alignment","Fine-tuning"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.05358","abstract":"Undesired model behaviors can emerge or re-emerge at any stage of training. Once observed, how effectively can we suppress them? To study this question, we first construct two model organisms--language models deliberately trained to exhibit a specific misalignment--that differ in what triggers the behavior. The narrow-trigger organism misbehaves only when the prompt contains a specific cue: it cheats on multiple-choice questions by following a planted hint that points to a wrong answer, and behaves normally otherwise. The broad-trigger organism has no such cue: after fine-tuning on insecure code, it gives harmful responses across a wide range of open-ended prompts. We then formalize post-hoc behavioral suppression and evaluate methods along three criteria: immediate suppression of the target behavior, durability under further training, and preservation of general capability. We compare s"},{"url":"https://arxiv.org/abs/2611.03725","id":"arxiv:2611.03725","title":"From Logs to Faults: Reference-Free Fault Localization for Retrieval-Augmented Generation Pipelines","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.03725.pdf","submittedDate":"2026-11-01","announceDate":"2026-11-04","tags":["Agentic RAG","Agentic Search","Error Attribution","Evaluation"],"authors":["Hira Naveed","Scott Barnett","Stefanus Kurniawan","John Grundy","Chetan Arora","Hourieh Khalajzadeh","Omar Haggag"],"date":"2026-11-04","topics":["Agentic RAG","Agentic Search","Error Attribution","Evaluation"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.03725","abstract":"Retrieval-Augmented Generation (RAG) pipelines are widely used for domain-specific question answering, yet locating faults remains manual and time-consuming. Fault localization is challenging because RAG pipelines consist of interdependent stages, where faults can propagate downstream, masking their origin, or remain undetected even when the final answer is correct. Existing evaluation approaches often focus on individual stages and rely on reference answers or code instrumentation. We present RAGLog, which detects and localizes faults across RAG stages using execution logs, without requiring reference answers or code instrumentation. RAGLog transforms heterogeneous API logs into a common RAG schema and combines rule-based, embedding-based, and LLM-based checks to identify faulty stages. We introduce a live fault injector and RAGLog Faults, a dataset of 3,134 runs from five RAG pipelines"},{"url":"https://arxiv.org/abs/2611.03723","id":"arxiv:2611.03723","title":"EMBERS: Empirically Motivated Robustness Testing of Deep Research Systems via Defect-Guided Fuzzing","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.03723.pdf","submittedDate":"2026-11-01","announceDate":"2026-11-04","tags":["Agent Safety","Reasoning","Evaluation","Fine-tuning"],"authors":["Shuochuan Li","Zan Wang","Dong Wang","Yuhang Jiang","Huajin Cui","Chen Zhang","Gang Wang","Junjie Chen"],"date":"2026-11-04","topics":["Agent Safety","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.03723","abstract":"Deep Research (DR) systems extend large language models into autonomous agents that decompose complex information needs, iteratively search the web, and synthesize evidence to answer challenging questions. However, their multi-stage execution may introduce robustness risks, as variations in user questions or intermediate search inputs may propagate across research stages and lead to incorrect answers. Existing evaluations focus on task-solving capabilities or robustness against external evidence disturbances, leaving intrinsic weaknesses in DR execution insufficiently explored. Thus, we conduct an empirical study of 1,932 execution trajectories from three representative DR systems and identify nine recurring defect categories across subquestion formulation, online search, and final reasoning. Guided by these findings, we propose EMBERS, an empirically motivated, defect-guided fuzzing fra"},{"url":"https://arxiv.org/abs/2611.03698","id":"arxiv:2611.03698","title":"Training LLM Agents to Automate LLM Post-Training with RSI-Dojo","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.03698.pdf","submittedDate":"2026-10-29","announceDate":"2026-11-04","tags":["Post-Training","Evaluation","Fine-tuning","Reflection"],"authors":["Shuzheng Gao","Zhaojian Yu","Penghao Yin","Yuling Shi","Kai Cai","Shilin He","Michael R. Lyu"],"date":"2026-11-04","topics":["Post-Training","Evaluation","Fine-tuning","Reflection"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.03698","abstract":"Recursive Self-Improvement (RSI) aims to enable AI systems to autonomously build and improve AI systems themselves, including models, harnesses, and underlying infrastructure. Within this broader agenda, a central capability is enabling agents to train and improve base models. However, existing studies on automated model training primarily focused on workflow- or harness-level optimizations, rather than internalizing the ability to conduct post-training into the model itself. Developing this capability requires executable model training environments that can produce high-quality trajectories demonstrating how to select data, train models, diagnose failures, and iteratively improve results. In this paper, we introduce RSI-Dojo, a collection of executable model training environments designed to teach LLM agents to conduct post-training. To construct RSI-Dojo, we develop RSI-Craft, an autom"},{"url":"https://arxiv.org/abs/2611.04289","id":"arxiv:2611.04289","title":"When Debate Amplifies Risk: Social-Bias Vulnerabilities in Multi-Agent Safety Deliberation","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04289.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Agentic Search","Agent Safety","Multi-Agent","Evaluation"],"authors":["Qinghua Mao","Xi Lin","Yuxin Qi","Zihao Xu","Jinze Gu","Yuliang Chen"],"date":"2026-11-04","topics":["Agentic Search","Agent Safety","Multi-Agent","Evaluation"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04289","abstract":"Retrieval-augmented Web applications increasingly employ multi-agent debate (MAD) to aggregate conflicting, noisy, and heterogeneous information, yet deliberation is fundamentally a social process susceptible to interpersonal dynamics. When retrieved Web sources contain latent hazards alongside safe factual content, social biases such as conformity pressure and authority deference can override evidence-grounded safety boundaries. In this work, we investigate whether the social structure of deliberation can paradoxically amplify latent Web safety risks. We introduce SafeConflict-Bias, a controlled counterfactual diagnostic protocol spanning six core Web risk categories, which holds queries and retrieved evidence strictly invariant while isolating conversational majority sway, authority cues, and confidence asymmetry. Empirical evaluation across diverse proprietary and open-source backbone"},{"url":"https://arxiv.org/abs/2611.03815","id":"arxiv:2611.03815","title":"AIRoA-0: Long-Horizon, Precise, Cross-Embodiment Manipulation from Handheld Data","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.03815.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["Post-Training","LLM Training","VLM Training","Evaluation"],"authors":["Yueh-Hua Wu","Kei Ota","Hanlong Li","Hayata Yuasa","Jason Wang","Kengo Ikeuchi","Kensuke Chiyoma","Makoto Sugiura","Masafumi Takahashi","Masatoshi Tateno","Naoaki Kanazawa","Nicola Scianca","Petr Khrapchenkov","Satoshi Otsubo","Takehiko Ohkawa","Takuya Okubo","Tatsuya Matsushima","Yuki Noguchi","Yuma Shin","Zixuan Zhong"],"date":"2026-11-04","topics":["Post-Training","LLM Training","VLM Training","Evaluation"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.03815","abstract":"AIRoA-0 (A-0) is a bimanual manipulation system learned from 16,151 hours of handheld demonstrations, with no robot data collected at any stage. The demonstrations are recorded with YUBI, our open-source handheld gripper, which lets people record manipulation data anywhere with no robot present. From a single instruction, A-0 sorts more than a dozen small parts into their numbered cells and changes the mop pads and brush of a robot vacuum; among other tasks, it unzips a pencil case and folds a towel. It performs these tasks using only a camera on each wrist, with no head or scene camera, at a site where none of its training data was recorded. Across the ten tasks of our evaluation, it averages a success rate of 78%, against 27% for the strongest of four other vision-language-action models post-trained on the same task demonstrations. We collect no teleoperation data and use no reinforcem"},{"url":"https://arxiv.org/abs/2611.03743","id":"arxiv:2611.03743","title":"EvoMemState: Evolving Memory State for Personal Agents","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.03743.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["Reasoning","Memory","Evaluation","RL for LLM"],"authors":["Zhishang Xiang","Yunbo Tang","Zhongqiao Liu","Junkai Chen","Zerui Chen","Qingguo Hu","Yuxuan Zhang","William Grant","Qinggang Zhang","Jinsong Su"],"date":"2026-11-04","topics":["Reasoning","Memory","Evaluation","RL for LLM"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.03743","abstract":"Long-term memory enables large language model (LLM) agents to provide continuous personalized assistance by retaining user information across interactions. Existing systems support this process through fact extraction, organization, updating, and retrieval, but largely maintain memories as independent facts. This fact-centric paradigm may overlook how new facts update, constrain, or conflict with earlier ones, while leaving their applicability, role, and priority for the current request implicit. In this paper, we introduce EvoMemState, a state-centric framework that augments persistent facts with two complementary states: Relational States that capture how facts remain valid and relate to one another as memory evolves, and a Reasoning State that determines how these facts should be applied to the current request. Specifically, EvoMemState consists of three key components: (i) Ontology-G"},{"url":"https://arxiv.org/abs/2611.05313","id":"arxiv:2611.05313","title":"MDSKILL: Learning to Internalize Skill Memory through Multi-View Distillation for Efficient Dynamic Agent Self-Evolution","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.05313.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Reasoning","Planning","Evaluation","RL for LLM"],"authors":["Dian Jin","Jinluan Yang","Kairong Han","Baohong Li","Zijing Hu","Yi He","Wenlin Zhong","Yunze Tong","Minqin Zhu","Linchuan Li","Yanan Niu","Kun Kuang"],"date":"2026-11-04","topics":["Reasoning","Planning","Evaluation","RL for LLM"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.05313","abstract":"Skill memories encode past experiences as textual prompts to improve reinforcement learning (RL) for self-evolving agents. Complementing RL, On-Policy Self-Distillation (OPSD) provides dense, fine-grained supervision to internalize knowledge from skill-guided trajectories and accelerate policy learning. However, self-generated memories often contain noisy supervision and functionally entangled, redundant, or conflicting knowledge, making direct distillation difficult. Under limited training budgets, these issues can hinder knowledge internalization and even degrade performance. To address this problem, we propose MDSKILL, a multi-view distillation approach for skill memory internalization. MDSKILL organizes skill memories into three complementary functional views (state grounding, action planning, and execution control) and selects high-quality skills using dynamic metrics to construct v"},{"url":"https://arxiv.org/abs/2611.04949","id":"arxiv:2611.04949","title":"HERIT: Enabling Global Access to Hanja-to-English Historical Translation by Mitigating Temporal Bias","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04949.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Agentic RAG","Agentic Search","LLM Training","Evaluation"],"authors":["Dayeon Jeong","Kyeongpil Kang"],"date":"2026-11-04","topics":["Agentic RAG","Agentic Search","LLM Training","Evaluation"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04949","abstract":"Historical archives are invaluable for multidisciplinary research but remain inaccessible globally due to severe language barriers. While manual translation is prohibitively expensive and time-consuming, simply applying existing machine translation models is inadequate due to unique linguistic nuances and the temporal bias inherent in scarce human-labeled corpora. To address these challenges, we propose HERIT, a systematic domain-adaptation pipeline that leverages retrieval-augmented generation (RAG) to generate high-quality pseudo-labeled data from abundant Hanja-Korean corpora. This approach substantially expands the training dataset, mitigating both data scarcity and temporal overfitting across different historical periods. Extensive automated and human evaluations demonstrate that HERIT consistently outperforms baselines. Finally, we translate previously untranslated portions of the "},{"url":"https://arxiv.org/abs/2611.04031","id":"arxiv:2611.04031","title":"Language Model Augmented Decision Transformer for Multi-Task Offline Reinforcement Learning","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.04031.pdf","submittedDate":"2026-11-02","announceDate":"2026-11-04","tags":["Evaluation","Alignment","Fine-tuning","RL for LLM"],"authors":["Xinbo Zhao","Yuhang Liu","Xin Zhang","Lei Le","Zhaohan Xi","Yu Yang","Yingxue Zhang"],"date":"2026-11-04","topics":["Evaluation","Alignment","Fine-tuning","RL for LLM"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.04031","abstract":"Offline multi-task reinforcement learning (MTRL) aims to learn a unified policy from heterogeneous offline datasets that generalizes across tasks. However, existing offline MTRL methods often struggle with two fundamental issues: severe per-task data scarcity and limited cross-task generalization. In this paper, we propose Language-Model Augmented Decision Transformer (LaMA-DT), a unified sequence-modeling framework that leverages a single large language model (LLM) for both trajectory augmentation and multi-task policy learning. LaMA-DT uses natural-language task descriptions to guide task-aligned trajectory augmentation through a set of supervised generation and alignment objectives, and incorporates a scoring-and-filtering mechanism to retain high-quality augmented trajectories. The same LLM is then repurposed as a language-conditioned Decision Transformer and fine-tuned on a mixture "},{"url":"https://arxiv.org/abs/2611.05003","id":"arxiv:2611.05003","title":"Unifying and Beyond the Theory of Pervasive Capability Degradation in LLM Post-training SFT from Feature Interference","source":"arxiv","pdf":"https://arxiv.org/pdf/2611.05003.pdf","submittedDate":"2026-11-03","announceDate":"2026-11-04","tags":["Post-Training","LLM Training","Interpretability","Fine-tuning"],"authors":["Hang Chen","Jiaying Zhu","Wenya Wang"],"date":"2026-11-04","topics":["Post-Training","LLM Training","Interpretability","Fine-tuning"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2611.05003","abstract":"Pervasive Capability Degradation (PCD) refers to the phenomenon in which supervised fine-tuning (SFT), while adapting a large language model (LLM) to a target task, often erodes the general capabilities acquired during pre-training. Prevailing explanations attribute PCD to macroscopic distribution shift and therefore lack microscopic manipulability, leaving existing mitigation methods without a complete theoretical foundation. In this paper, we first develop a bottom-up geometric theory of PCD grounded in feature interference under superposition: narrow-domain SFT data disrupt the almost-orthogonal feature structure formed during pre-training, and the resulting interference drives activations across decision hyperplanes in the output Laguerre-Voronoi geometry, flipping predictions on general tasks. This theory unifies existing methods into six paradigms and reveals both the source of the"}],"archive":[],"latestPath":"data/latest.json"};
